<script setup lang="ts">
definePageMeta({middleware:'auth'});useHead({title:'حساب کاربری'});const{api,token}=useShopApi();const{data,refresh}=await useAsyncData('profile-dashboard',()=>api<any>('/profile/dashboard'));const form=reactive({name:'',email:'',national_code:'',birth_date:''}),saved=ref(false),error=ref('');watchEffect(()=>{if(data.value?.user)Object.assign(form,{name:data.value.user.name||'',email:data.value.user.email||'',national_code:data.value.user.national_code||'',birth_date:data.value.user.birth_date||''})});async function save(){error.value='';try{await api('/auth/profile',{method:'PUT',body:form});saved.value=true;await refresh()}catch(e:any){error.value=e?.data?.message||Object.values(e?.data?.errors||{})[0]?.[0]||'ذخیره اطلاعات انجام نشد.'}}async function logout(){await api('/auth/logout',{method:'DELETE'});token.value=null;await navigateTo('/')}
const links=[['/profile/orders','سفارش‌های من','پیگیری و مشاهده فاکتور'],['/profile/addresses','آدرس‌های من','مدیریت نشانی‌های تحویل'],['/profile/favorites','علاقه‌مندی‌ها','محصولات نشان‌شده'],['/profile/saved','مقالات ذخیره‌شده','مطالب برای مطالعه بعدی'],['/profile/tickets','پشتیبانی','تیکت‌ها و پاسخ‌ها'],['/profile/returns','مرجوعی‌ها','پیگیری درخواست‌های بازگشت'],['/profile/notifications','اعلان‌ها','پیام‌های حساب کاربری']];
</script>
<template><div class="mx-auto max-w-7xl px-4 py-10"><div class="rounded-3xl bg-brand-900 p-6 text-white md:flex md:items-center md:justify-between"><div><h1 class="text-2xl font-black">{{data?.user?.name||'کاربر هنرمارکت'}}</h1><p dir="ltr" class="mt-2 text-right text-sm text-brand-100">{{data?.user?.mobile}}</p></div><button class="mt-4 rounded-xl bg-white/10 px-5 py-2 text-sm font-bold md:mt-0" @click="logout">خروج از حساب</button></div><div class="mt-6 grid gap-4 sm:grid-cols-3"><div v-for="item in [['همه سفارش‌ها',data?.orders_count||0],['سفارش‌های جاری',data?.pending_orders||0],['علاقه‌مندی‌ها',data?.favorites_count||0]]" :key="String(item[0])" class="rounded-2xl border bg-white p-5"><p class="text-sm text-slate-400">{{item[0]}}</p><p class="mt-3 text-2xl font-black">{{item[1]}}</p></div></div><div class="mt-6 grid gap-6 lg:grid-cols-[1fr_1.3fr]"><section class="grid gap-3 sm:grid-cols-2 lg:grid-cols-1"><NuxtLink v-for="item in links" :key="item[0]" :to="item[0]" class="group flex items-center justify-between rounded-2xl border bg-white p-4 transition hover:border-brand-300 hover:shadow-soft"><div><b>{{item[1]}}</b><p class="mt-1 text-xs text-slate-400">{{item[2]}}</p></div><span class="text-brand-700 transition group-hover:-translate-x-1">←</span></NuxtLink></section><form class="h-fit rounded-2xl border bg-white p-6" @submit.prevent="save"><h2 class="text-xl font-black">اطلاعات شخصی</h2><p v-if="error" class="mt-4 rounded-xl bg-rose-50 p-3 text-sm text-rose-700">{{error}}</p><div class="mt-6 grid gap-5 sm:grid-cols-2"><label><span class="mb-2 block text-sm font-bold">نام و نام خانوادگی</span><input v-model="form.name" required class="h-11 w-full rounded-xl border px-3"></label><label><span class="mb-2 block text-sm font-bold">ایمیل</span><input v-model="form.email" dir="ltr" type="email" class="h-11 w-full rounded-xl border px-3 text-left"></label><label><span class="mb-2 block text-sm font-bold">کد ملی</span><input v-model="form.national_code" dir="ltr" maxlength="10" class="h-11 w-full rounded-xl border px-3 text-left"></label><label><span class="mb-2 block text-sm font-bold">تاریخ تولد</span><input v-model="form.birth_date" dir="ltr" type="date" class="h-11 w-full rounded-xl border px-3"></label></div><button class="mt-6 rounded-xl bg-brand-700 px-6 py-3 font-bold text-white">{{saved?'ذخیره شد ✓':'ذخیره تغییرات'}}</button></form></div></div></template>
